/**
 * Schema migrations, applied at server start (see src/instrumentation.ts).
 *
 * Contract
 *  - SQL migrations live in drizzle/migrations (generated by drizzle-kit, committed). In the Docker
 *    image they are copied to /app/drizzle/migrations; override with MIGRATIONS_DIR.
 *  - Applied migrations are recorded in drizzle.__drizzle_migrations, so re-running is a no-op.
 *  - A session-level Postgres advisory lock serialises concurrent starters (several replicas, or a
 *    restart racing an old instance): the second waits, then finds nothing left to apply.
 *  - Everything runs on ONE dedicated connection (not the request pool) so lock + migration share
 *    a session; the connection is closed afterwards.
 */
import path from 'node:path';
import { sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import pg from 'pg';
import { getDatabaseUrl } from '@/lib/server/env';
import { isDbUnavailableError } from '@/lib/server/errors';
import { logger } from '@/lib/server/logger';
import type { Db } from './client';
import { sweepChatMessages, sweepYoutubeCache } from './maintenance';
import * as schema from './schema';

const log = logger.child({ component: 'db.migrate' });

/** App-wide constant key for pg_advisory_lock (any bigint; unique to this app's migrations). */
export const MIGRATION_LOCK_KEY = 7_261_946_001;

export function migrationsDir(): string {
  return process.env.MIGRATIONS_DIR?.trim() || path.join(process.cwd(), 'drizzle', 'migrations');
}

/**
 * Run `apply` while holding the migration advisory lock on `db`'s session.
 * `db` must be bound to a single connection (pg.Client / PGlite), never a pool.
 */
export async function withMigrationLock<T>(db: Db, apply: () => Promise<T>): Promise<T> {
  const key = sql.raw(MIGRATION_LOCK_KEY.toString()); // constant, not user input
  await db.execute(sql`select pg_advisory_lock(${key})`);
  try {
    return await apply();
  } finally {
    await db.execute(sql`select pg_advisory_unlock(${key})`);
  }
}

export interface MigrateOptions {
  connectionString?: string;
  migrationsFolder?: string;
}

/** Connect, lock, apply pending migrations, run boot-time sweeps, disconnect. Throws on failure. */
export async function runMigrations(opts: MigrateOptions = {}): Promise<void> {
  const migrationsFolder = opts.migrationsFolder ?? migrationsDir();
  const client = new pg.Client({
    connectionString: opts.connectionString ?? getDatabaseUrl(),
    connectionTimeoutMillis: 5_000,
    application_name: 'mkmovies-migrate',
  });
  client.on('error', (err) => log.warn('migration connection error', { err }));
  await client.connect();
  try {
    const db = drizzle(client, { schema }) as unknown as Db;
    const started = Date.now();
    await withMigrationLock(db, () => migrate(drizzle(client), { migrationsFolder }));
    log.info('migrations up to date', { migrationsFolder, ms: Date.now() - started });
    const [chat, yt] = await Promise.all([sweepChatMessages(db), sweepYoutubeCache(db)]);
    if (chat || yt) log.info('boot sweep', { chatMessages: chat, youtubeCache: yt });
  } finally {
    await client.end().catch(() => {});
  }
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/**
 * Boot entry point. Skips (with a warning) when DATABASE_URL is missing or MIGRATE_ON_BOOT=false,
 * so `next build` and DB-less health checks work. Retries while Postgres is still starting
 * (up to ~MIGRATE_MAX_WAIT_MS, default 60 s), then throws so the container restarts loudly
 * instead of serving against an unmigrated schema.
 */
export async function migrateOnBoot(): Promise<'skipped' | 'done'> {
  if (process.env.MIGRATE_ON_BOOT?.trim().toLowerCase() === 'false') {
    log.warn('MIGRATE_ON_BOOT=false — skipping migrations');
    return 'skipped';
  }
  if (!process.env.DATABASE_URL?.trim()) {
    log.warn('DATABASE_URL is not set — skipping migrations (DB features will answer 503)');
    return 'skipped';
  }
  const maxWait = Number(process.env.MIGRATE_MAX_WAIT_MS) || 60_000;
  const deadline = Date.now() + maxWait;
  for (let attempt = 1; ; attempt++) {
    try {
      await runMigrations();
      return 'done';
    } catch (err) {
      const retryable = isDbUnavailableError(err);
      if (!retryable || Date.now() + 2_000 > deadline) {
        log.error('migrations failed', { attempt, err });
        throw err;
      }
      const delay = Math.min(1_000 * 2 ** (attempt - 1), 8_000);
      log.warn('database not reachable yet; retrying migrations', { attempt, delayMs: delay });
      await sleep(delay);
    }
  }
}
